<?php get_header(); $members = get_posts(['post_type' => 'team_member', 'post_status' => 'publish', 'posts_per_page' => -1, 'post__not_in' => arbok_hidden_team_ids(), 'orderby' => ['menu_order' => 'ASC', 'title' => 'ASC']]); $groups = []; foreach ($members as $member) { $group = get_post_meta($member->ID, 'team_group', true) ?: 'ARBOK leadership'; $groups[$group][] = $member; } ?>
<section class="page-hero page-hero--compact team-archive-hero"><div class="shell"><?php arbok_breadcrumbs(); ?><div class="archive-hero-row"><div><p class="eyebrow">ARBOK leadership</p><h1>Technical depth and international execution</h1><p class="lede">Engineering, environmental systems, project delivery, finance, government relations and global partnerships.</p></div><div class="archive-hero-mark"><?php echo esc_html(count($members)); ?><small>team profiles</small></div></div></div></section>
<?php foreach ($groups as $group_name => $group_members) : ?><section class="section team-group"><div class="shell"><div class="section-heading"><div><p class="eyebrow dark">ARBOK team</p><h2><?php echo esc_html($group_name); ?></h2></div></div><div class="grid team-grid"><?php foreach ($group_members as $post) : setup_postdata($post); $member_slug = get_post_field('post_name'); ?><article class="person-card person-card--<?php echo esc_attr($member_slug); ?>"><a class="person-media" href="<?php the_permalink(); ?>"><?php if (has_post_thumbnail()) : the_post_thumbnail('medium_large', ['alt' => get_the_title()]); else : ?><img src="<?php echo esc_url(get_template_directory_uri() . '/assets/images/arbok-logo.png'); ?>" alt=""><?php endif; ?></a><div><p class="card-meta"><?php echo esc_html($group_name); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(arbok_clean_summary((string) arbok_field('role', false, get_the_excerpt()), '', 12)); ?></p><a class="text-link" href="<?php the_permalink(); ?>">View profile <span>↗</span></a></div></article><?php endforeach; wp_reset_postdata(); ?></div></div></section><?php endforeach; ?>
<?php get_footer(); ?>
